const inputData = $input.first().json;

// Payload de teste fictício ou payload real recebido da Evolution API
const body = inputData.body || inputData;

const eventName = body.event || body.event_name || 'messages.upsert';
const instance = body.instance || body.instance_name || 'teste_instance';
const dataObj = body.data || body.payload || body;

// Extração normalizada de contato e mensagem
const remoteJid = (dataObj.key && dataObj.key.remoteJid) || (dataObj.sender) || '5511999999999@s.whatsapp.net';
const cleanPhone = remoteJid.replace(/@.*$/, '').replace(/[^0-9]/g, '');
const formattedPhone = cleanPhone ? '+' + cleanPhone : '+5511999999999';

const messageId = (dataObj.key && dataObj.key.id) || dataObj.id || 'TEST_MSG_' + Date.now();
const textContent = (dataObj.message && (dataObj.message.conversation || dataObj.message.extendedTextMessage?.text)) || dataObj.content || 'Mensagem de teste controlada Evolution API';
const pushName = dataObj.pushName || dataObj.sender_name || null;

// Contrato de Normalização Interna SDTech Soluctions
const normalizedEvent = {
  source: "evolution_api",
  event: eventName,
  instance: instance,
  received_at: new Date().toISOString(),
  tenant_id: null, // Resolvido posteriormente via tabela channels
  contact: {
    phone: formattedPhone,
    name: pushName
  },
  message: {
    id: messageId,
    type: "text",
    direction: "inbound",
    text: textContent,
    timestamp: new Date().toISOString()
  },
  raw_event: body
};

return [{
  json: {
    status: "success",
    code: "EVOLUTION_TEST_PROCESSED",
    message: "Webhook da Evolution API recebido e normalizado com sucesso (sem alteração no banco ou IA)",
    normalized_event: normalizedEvent,
    timestamp: new Date().toISOString()
  }
}];
